/* Local demonstration actions. No network requests or live transactions. */
const adminOptions=(list,value)=>list.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('');
const adminInput=(name,label,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
function adminForm(kind,id,body,title){clubDialog(`<form class="stack" data-form="${kind}" data-id="${id||''}">${body}<button class="btn">Salvar na demonstração</button></form>`,title)}
function clientDialog(c={}){adminForm('admin-client',c.id,`<div class="form-grid">${adminInput('name','Nome fictício',c.name||'','text','required minlength="2"')}${adminInput('email','E-mail fictício',c.email||'','email','required')}${adminInput('phone','Telefone fictício',c.phone||'')}${adminInput('cep','CEP',c.cep||'01001-000','text','required pattern="[0-9]{5}-?[0-9]{3}"')}${adminInput('street','Rua',c.street||'Rua Exemplo','text','required')}${adminInput('number','Número',c.number||'123','text','required')}${adminInput('city','Cidade',c.city||'São Paulo','text','required')}${adminInput('state','Estado',c.state||'SP','text','required maxlength="2"')}</div><label>Observações<textarea name="notes" maxlength="800">${esc(c.notes||'')}</textarea></label>`,c.id?'Editar cliente':'Novo cliente de demonstração')}
function productDialog(p){const inv=ops.inventory[p?.id]||{};adminForm('admin-product',p?.id,`<div class="form-grid">${adminInput('name','Nome da peça',p?.name||'','text','required minlength="3"')}${adminInput('price','Preço ilustrativo',p?.price||89.9,'number','required min="1" step=".01"')}${adminInput('sku','SKU',inv.sku||'AMG-NOVO','text','required')}${adminInput('stock','Estoque disponível',inv.stock??10,'number','required min="0" step="1"')}${adminInput('cost','Custo unitário',inv.cost||25,'number','required min="0" step=".01"')}<label>Coleção<select name="category">${adminOptions(['Cristãos','Católicos','Evangélicos','Presentes','Personalizados'],p?.category)}</select></label><label>Imagem conceitual<select name="img">${['Cruz','Nossa Senhora','Pomba','Palavra Fé','Sagrada Família','Bíblia'].map((x,i)=>`<option value="${i}" ${p?.img===i?'selected':''}>${x}</option>`).join('')}</select></label><label>Visibilidade<select name="active"><option value="true" ${p?.active!==false?'selected':''}>Publicado no catálogo</option><option value="false" ${p?.active===false?'selected':''}>Oculto do catálogo</option></select></label></div><label>Descrição<textarea name="desc" required minlength="10" maxlength="700">${esc(p?.desc||'Peça decorativa cristã em impressão 3D. Modelo conceitual de demonstração.')}</textarea></label>`,p?'Editar produto e estoque':'Novo produto de demonstração')}
function adminExport(kind){let headers,rows;if(kind==='pedidos'||kind==='envios'){headers=['Pedido','Cliente','Origem','Total','Situação','Rastreio'];rows=ops.orders.filter(o=>kind!=='envios'||['Pronto para envio','Enviado','Entregue'].includes(o.status)).map(o=>[o.id,opClient(o.customerId)?.name,o.type,o.total,o.status,o.tracking])}else if(kind==='assinaturas'){headers=['Contrato','Cliente','Perfil','Mensalidade','Situação','Renovação'];rows=ops.subscriptions.map(s=>[s.id,opClient(s.customerId)?.name,s.profile,s.price,s.status,s.nextRenewal])}else if(kind==='clientes'){headers=['Cliente','Nome','E-mail fictício','Cidade','Situação'];rows=ops.clients.map(c=>[c.id,c.name,c.email,c.city,c.status])}else if(kind==='producao'){headers=['Ordem','Pedido','Etapa','Máquina','Horas','Responsável'];rows=ops.jobs.map(j=>[j.id,j.orderId,j.stage,j.printer,j.hours,j.assignee])}else if(kind==='produtos'){headers=['SKU','Produto','Preço','Estoque','Custo','Publicado'];rows=products.map(p=>[ops.inventory[p.id]?.sku,p.name,p.price,ops.inventory[p.id]?.stock,ops.inventory[p.id]?.cost,p.active!==false?'Sim':'Não'])}else{headers=['Cobrança','Cliente','Descrição','Valor','Situação','Vencimento'];rows=ops.charges.map(c=>[c.id,opClient(c.customerId)?.name,c.description,c.amount,c.status,c.due])}exportOpsCSV(kind,headers,rows);toast('CSV da demonstração preparado.')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-admin]');if(!b)return;const a=b.dataset.admin,id=b.dataset.id,o=opOrder(id),s=opSubscription(id);
 if(a==='clear-filter'){adminState.search='';adminState.filter='Todos';render()}
 if(a==='export')adminExport(b.dataset.kind);
 if(a==='new-client')clientDialog();if(a==='edit-client')clientDialog(opClient(id));
 if(a==='archive-client'){const c=opClient(id);adminForm('admin-archive',id,`<p>O cadastro de ${esc(c.name)} ficará ${c.status==='Inativo'?'ativo':'inativo'}. Pedidos e assinaturas continuam no histórico.</p>`,c.status==='Inativo'?'Reativar cadastro':'Arquivar cadastro')}
 if(a==='edit-order'&&o)adminForm('admin-order',id,`<label>Situação<select name="status">${adminOptions(['Aguardando pagamento','Confirmado','Em produção','Em acabamento','Pronto para envio','Enviado','Entregue','Cancelado'],o.status)}</select></label><div class="form-grid"><label>Prioridade<select name="priority">${adminOptions(['Normal','Alta'],o.priority)}</select></label>${adminInput('due','Expedição prevista',o.due,'date','required')}</div><label>Observações internas<textarea name="notes" maxlength="800">${esc(o.notes||'')}</textarea></label><div class="notice">Alterar a situação não cria cobrança nem reembolso. Registre pagamentos no Financeiro e rastreio na Expedição.</div>`,'Atualizar pedido');
 if(a==='production-add'&&o){productionOps(id);render();toast('Pedido na fila de produção.')}
 if(a==='ship-order'&&o)adminForm('admin-ship',id,`<p>${esc(o.id)} · ${esc(opClient(o.customerId)?.name)}</p><label>Transportadora<select name="carrier">${adminOptions(['Correios (simulação)','Transportadora parceira (simulação)'],o.carrier)}</select></label>${adminInput('tracking','Código de rastreio fictício',o.tracking||'DEMO'+Date.now().toString().slice(-9),'text','required pattern="[A-Za-z0-9-]{5,30}"')}<div class="notice">Registra uma expedição local. Nenhuma etiqueta, postagem ou remessa real será contratada.</div>`,'Despachar na demonstração');
 if(a==='label'&&o)clubDialog(`<div class="demo-label"><h3>ETIQUETA DE DEMONSTRAÇÃO</h3><p>Sem validade para postagem</p><hr><strong>${esc(opClient(o.customerId)?.name)}</strong><p>${esc(o.address.street)}, ${esc(o.address.number)}<br>${esc(o.address.city)}/${esc(o.address.state)} · ${esc(o.address.cep)}</p><hr><strong>${esc(o.tracking||'Sem rastreio')}</strong><p>${esc(o.id)} · ${esc(o.carrier)}</p></div>`,'Etiqueta ilustrativa');
 if(a==='delivered'&&o){setOrderOps(id,'Entregue');render();toast('Entrega registrada na simulação.')}
 if(a==='pay-charge'){payChargeOps(id);const ch=ops.charges.find(x=>x.id===id);if(ch?.orderId&&opOrder(ch.orderId)?.type==='Clube')productionOps(ch.orderId);render();toast('Recebimento confirmado na demonstração.')}
 if(a==='refund-charge')adminForm('admin-refund',id,`<p>O registro financeiro ficará como Estornado. Nenhum valor real será movimentado.</p><label>Motivo<textarea name="reason" required minlength="5" maxlength="300"></textarea></label>`,'Simular estorno');
 if(a==='renew-cycle'&&s){if(s.status!=='Ativa'){toast('Retome a assinatura antes de gerar um ciclo.');return}adminForm('admin-renew',id,`<p>${esc(s.id)} · ${opDate(s.nextRenewal)} · ${money(s.price)}</p><label>Resultado da renovação simulada<select name="result">${adminOptions(s.payment==='pix'?['Pendente']:['Pago','Pendente','Recusado'],'Pago')}</select></label><div class="notice">Será criado um pedido e uma cobrança local para o próximo ciclo. Pix requer confirmação de cada mensalidade.</div>`,'Gerar próximo ciclo')}
 if(a==='sub-status'&&s){if(b.dataset.status==='Cancelada'){$('[data-op="cancel-subscription"][data-id="'+id+'"]')?.click();if(!$('#overlay-root').children.length)adminForm('admin-sub-state',id,`<p>Próximas renovações serão interrompidas. Pedidos existentes permanecem no histórico.</p><input type="hidden" name="status" value="Cancelada">`,'Cancelar assinatura demo')}else{s.status=b.dataset.status;s.history.unshift({date:OPS_DAY,label:'Situação alterada pela equipe: '+s.status});auditOps('Assinatura '+s.status,id);render();toast('Situação da assinatura atualizada.')}}
 if(a==='new-job')adminForm('admin-job','',`<label>Pedido confirmado<select name="orderId" required>${ops.orders.filter(x=>x.status==='Confirmado'&&!ops.jobs.some(j=>j.orderId===x.id&&j.stage!=='Pronto')).map(x=>`<option value="${x.id}">${x.id} · ${esc(opClient(x.customerId)?.name)}</option>`).join('')}</select></label><div class="form-grid"><label>Máquina<select name="printer">${adminOptions(ops.printers.filter(x=>x.status!=='Manutenção').map(x=>x.name))}</select></label>${adminInput('hours','Horas estimadas',6,'number','required min=".5" max="100" step=".5"')}${adminInput('assignee','Responsável','Pedro','text','required')}</div>`,'Criar ordem de produção');
 if(a==='advance-job'){const j=ops.jobs.find(x=>x.id===id),stages=['Fila','Impressão','Acabamento','Conferência','Pronto'];if(j&&j.stage!=='Pronto'){j.stage=stages[stages.indexOf(j.stage)+1];setOrderOps(j.orderId,j.stage==='Pronto'?'Pronto para envio':j.stage==='Impressão'?'Em produção':'Em acabamento');auditOps('Produção: '+j.stage,id);render();toast(j.stage==='Pronto'?'Pedido liberado para expedição.':'Etapa de produção atualizada.')}}
 if(a==='printer-state'){const p=ops.printers.find(x=>x.id===id);adminForm('admin-printer',id,`<p>${esc(p.name)}</p><label>Situação<select name="status">${adminOptions(['Disponível','Imprimindo','Manutenção'],p.status)}</select></label>`,'Situação da máquina')}
 if(a==='new-expense')adminForm('admin-expense','',`${adminInput('name','Descrição fictícia','','text','required minlength="3"')}<div class="form-grid">${adminInput('amount','Valor',0,'number','required min=".01" step=".01"')}${adminInput('date','Data',OPS_DAY,'date','required')}<label>Categoria<select name="category">${adminOptions(['Produção','Embalagem','Frete','Operação','Outros'])}</select></label><label>Situação<select name="status">${adminOptions(['Previsto','Pago'])}</select></label></div>`,'Lançar despesa demo');
 if(a==='pay-expense'){const x=ops.expenses.find(x=>x.id===id);if(x){x.status='Pago';auditOps('Despesa paga na simulação',id);render();toast('Despesa atualizada.')}}
 if(a==='new-product')productDialog();if(a==='edit-product')productDialog(products.find(x=>x.id===id));
 if(a==='moderate'){hiddenPrayers=hiddenPrayers.includes(id)?hiddenPrayers.filter(x=>x!==id):[...hiddenPrayers,id];persist('hidden-prayers',hiddenPrayers);auditOps('Visibilidade do pedido de oração alterada',id);render();toast('Visibilidade atualizada no mural local.')}
 if(a==='new-team'||a==='edit-team'){const u=ops.team.find(x=>x.id===id)||{};adminForm('admin-team',u.id,`${adminInput('name','Nome fictício',u.name||'','text','required')}${adminInput('email','E-mail fictício',u.email||'','email','required')}<label>Perfil ilustrativo<select name="role">${adminOptions(['Administrador','Atendimento','Produção','Financeiro'],u.role)}</select></label><label>Situação<select name="status">${adminOptions(['Ativo','Inativo'],u.status)}</select></label><small>Perfil não aplica restrições reais neste protótipo.</small>`,'Integrante de demonstração')}
 if(a==='new-order')adminForm('admin-new-order','',`<label>Cliente<select name="customerId" required>${ops.clients.filter(c=>c.status==='Ativo').map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.email)}</option>`).join('')}</select></label><label>Produto<select name="productId">${products.filter(p=>p.active!==false).map(p=>`<option value="${p.id}">${esc(p.name)} · ${money(p.price)}</option>`).join('')}</select></label><div class="form-grid">${adminInput('qty','Quantidade',1,'number','required min="1" max="50" step="1"')}${adminInput('shipping','Frete ilustrativo',18.9,'number','required min="0" step=".01"')}<label>Pagamento<select name="payment">${adminOptions(['Pix pendente','Cartão pago (simulado)'])}</select></label>${adminInput('due','Expedição prevista','2026-11-18','date','required')}</div><div class="notice">Pedido avulso com um produto. Nenhuma cobrança real será criada.</div>`,'Novo pedido manual');
});
document.addEventListener('submit',e=>{const f=e.target,t=f.dataset.form,types=['admin-filter','admin-global-search','edition','admin-reply','campaign','settings','admin-client','admin-archive','admin-product','admin-order','admin-ship','admin-refund','admin-renew','admin-sub-state','admin-job','admin-printer','admin-expense','admin-team','admin-new-order'];if(!types.includes(t))return;e.preventDefault();if(!f.reportValidity())return;const fd=new FormData(f),d=Object.fromEntries(fd),id=f.dataset.id;
 if(t==='admin-filter'){adminState.search=d.search;adminState.filter=d.status;render();return}
 if(t==='admin-global-search'){adminState.globalSearch=d.query?.trim()||'';navigate('#/admin/busca');render();return}
 if(t==='admin-client'){const existing=ops.clients.find(c=>c.email.toLowerCase()===d.email.toLowerCase()&&c.id!==id);if(existing){toast('Este e-mail já está cadastrado. Edite o cliente existente.');return}let c=opClient(id);if(c)Object.assign(c,d);else{c={id:opId('CLI'),...d,status:'Ativo',created:OPS_DAY};ops.clients.unshift(c)}auditOps('Cadastro do cliente salvo',c.id)}
 if(t==='admin-archive'){const c=opClient(id);c.status=c.status==='Inativo'?'Ativo':'Inativo';auditOps('Cliente '+c.status.toLowerCase(),id)}
 if(t==='admin-product'){const data={name:d.name,price:Number(d.price),category:d.category,tags:[d.category,'Presentes'],img:Number(d.img),active:d.active==='true',desc:d.desc};let p=products.find(x=>x.id===id);if(p){Object.assign(p,data);ops.productOverrides[id]={...(ops.productOverrides[id]||{}),...data};const extra=ops.extraProducts.find(x=>x.id===id);if(extra)Object.assign(extra,data)}else{p={id:opId('peca').toLowerCase(),...data,tag:'Nova peça',sizes:['15 cm','20 cm','25 cm'],colors:['Marfim','Areia','Terracota']};products.push(p);ops.extraProducts.push(p)}ops.inventory[p.id]={sku:d.sku,stock:Number(d.stock),cost:Number(d.cost)};auditOps('Produto e estoque atualizados',p.id)}
 if(t==='admin-order'){const o=opOrder(id);o.priority=d.priority;o.due=d.due;o.notes=d.notes;setOrderOps(id,d.status)}
 if(t==='admin-ship'){const o=opOrder(id);o.carrier=d.carrier;o.tracking=d.tracking;setOrderOps(id,'Enviado')}
 if(t==='admin-refund'){const ch=ops.charges.find(x=>x.id===id);ch.status='Estornado';ch.refundReason=d.reason;const o=opOrder(ch.orderId);if(o&&!['Enviado','Entregue'].includes(o.status)){setOrderOps(o.id,'Cancelado');ops.jobs=ops.jobs.filter(j=>j.orderId!==o.id)}auditOps('Estorno simulado registrado',id)}
 if(t==='admin-renew'){const s=opSubscription(id);const oid=generateClubCycle(s,d.result);if(!oid){toast('Este ciclo já possui uma cobrança. Confira o financeiro.');return}if(d.result==='Pago')productionOps(oid)}
 if(t==='admin-sub-state'){const s=opSubscription(id);s.status=d.status;s.history.unshift({date:OPS_DAY,label:'Cancelamento registrado pela equipe.'});auditOps('Assinatura cancelada',id)}
 if(t==='admin-job'){if(!opOrder(d.orderId)){toast('Não há pedido disponível. Confirme um pedido primeiro.');return}productionOps(d.orderId);const j=ops.jobs.find(j=>j.orderId===d.orderId&&j.stage!=='Pronto');Object.assign(j,{printer:d.printer,hours:Number(d.hours),assignee:d.assignee});auditOps('Ordem de produção configurada',j.id)}
 if(t==='admin-printer'){Object.assign(ops.printers.find(x=>x.id===id),d);auditOps('Situação de máquina atualizada',id)}
 if(t==='admin-expense'){const x={id:opId('DES'),...d,amount:Number(d.amount)};ops.expenses.unshift(x);auditOps('Despesa lançada',x.id)}
 if(t==='admin-team'){const u=ops.team.find(x=>x.id===id);if(u)Object.assign(u,d);else ops.team.push({id:opId('U'),...d});auditOps('Integrante demo atualizado',d.name)}
 if(t==='admin-new-order'){const c=opClient(d.customerId),p=products.find(x=>x.id===d.productId);if(!c||!p){toast('Cadastre um cliente e um produto ativo primeiro.');return}const oid=opId('PED'),cid=opId('COB'),paid=d.payment.startsWith('Cartão'),qty=Number(d.qty),total=p.price*qty+Number(d.shipping);ops.orders.unshift({id:oid,customerId:c.id,type:'Loja',items:[{id:p.id,name:p.name,img:p.img,price:p.price,qty,color:p.colors[0],size:p.sizes[0]}],total,shipping:Number(d.shipping),status:paid?'Confirmado':'Aguardando pagamento',created:OPS_DAY,due:d.due,address:{...c},chargeId:cid,tracking:'',carrier:'A definir',priority:'Normal',notes:'Pedido manual de demonstração.'});ops.charges.unshift({id:cid,customerId:c.id,orderId:oid,amount:total,method:paid?'card':'pix',status:paid?'Pago':'Pendente',due:OPS_DAY,paidAt:paid?OPS_DAY:null,description:'Pedido manual',cycle:OPS_DAY.slice(0,7)});auditOps('Pedido manual criado',oid)}
 if(t==='edition'){const profiles=Object.fromEntries(['Católica','Evangélica','Cristã'].map(p=>[p,fd.getAll('items-'+p)]));if(Object.values(profiles).some(a=>a.length===0)){toast('Selecione pelo menos uma peça para cada perfil de cesta.');return}Object.assign(ops.settings,{edition:d.edition,editionMonth:d.month,dispatchDay:Number(d.dispatchDay),profiles});auditOps('Edição mensal preparada',d.edition)}
 if(t==='admin-reply'){const ticket=ops.tickets.find(x=>x.id===id);if(d.message?.trim())ticket.messages.push({by:'equipe',text:d.message,date:OPS_DAY});Object.assign(ticket,{status:d.status,assignee:d.assignee});auditOps('Atendimento atualizado',id)}
 if(t==='campaign'){const sub=readStore('newsletter',null);ops.campaigns.unshift({id:opId('ORA'),...d,recipients:sub?.subscribed?1:0});auditOps('Envio de oração simulado',d.subject)}
 if(t==='settings'){Object.assign(ops.settings,{...d,price:Number(d.price),dispatchDay:Number(d.dispatchDay),lowStock:Number(d.lowStock)});auditOps('Configurações da loja atualizadas','Loja')}
 saveOps();closeOverlay();render();toast('Alteração salva na demonstração.');
});
render();
